-- Transactional integration test: all synthetic users, tenants, records are rolled back.
BEGIN;
CREATE TEMP TABLE launch_test_result(result jsonb);
ALTER TABLE pg_temp.launch_test_result ENABLE ROW LEVEL SECURITY;
DO $$
DECLARE i int; au uuid; ru uuid; u uuid; r uuid; m uuid; first_m uuid; first_u uuid; first_auth uuid; first_reader uuid; other_auth uuid; rowid uuid; reader_id uuid; q jsonb; denied boolean; started timestamptz:=clock_timestamp(); checks int:=0;
BEGIN
 FOR i IN 1..45 LOOP
  au:=gen_random_uuid();ru:=gen_random_uuid();
  INSERT INTO auth.users(id,email,email_confirmed_at,raw_user_meta_data) VALUES(au,'launch-admin-'||au||'@example.invalid',now(),'{"name":"Synthetic Admin"}'),(ru,'launch-reader-'||ru||'@example.invalid',now(),'{"name":"Synthetic Reader"}');
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',au,'role','authenticated')::text,true);u:=mp_private.actor();
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',ru,'role','authenticated')::text,true);r:=mp_private.actor();
  INSERT INTO public."Mosque"(name,slug,status) VALUES('Synthetic Launch Tenant '||i,gen_random_uuid()::text,'ACTIVE') RETURNING id INTO m;
  INSERT INTO public."MosqueSettings"("mosqueId",plan) VALUES(m,CASE WHEN i<=15 THEN 'BASIC' WHEN i<=30 THEN 'PRO' ELSE 'ENTERPRISE' END);
  INSERT INTO public."MosqueMembership"("mosqueId","userId",status) VALUES(m,u,'ACTIVE'),(m,r,'ACTIVE');
  INSERT INTO public."MosqueAdmin"("mosqueId","userId") VALUES(m,u);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',au,'role','authenticated')::text,true);
  q:=public.mp_save_record(m,'donasi','{"name":"Synthetic Donor","date":"2026-10-25","amount":"10000","method":"Tunai","purpose":"Test"}');
  IF q->'record'->'data'->>'amount'<>'10000' THEN RAISE EXCEPTION 'save_failed'; END IF;
  q:=public.mp_workspace(m);IF (q->>'canWrite')::boolean IS NOT TRUE OR jsonb_array_length(q->'records')<>1 THEN RAISE EXCEPTION 'admin_access_failed'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',ru,'role','authenticated')::text,true);
  q:=public.mp_workspace(m);IF (q->>'canWrite')::boolean IS NOT FALSE OR jsonb_array_length(q->'records')<>1 THEN RAISE EXCEPTION 'reader_access_failed'; END IF;
  denied:=false;BEGIN PERFORM public.mp_save_record(m,'donasi','{"amount":"999999"}');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  IF NOT denied THEN RAISE EXCEPTION 'reader_write_allowed'; END IF;
  IF i=1 THEN first_m:=m;first_u:=u;first_auth:=au;first_reader:=ru;rowid:=(q->'records'->0->>'id')::uuid;END IF;
  IF i=2 THEN other_auth:=au;END IF;
  checks:=checks+4;
 END LOOP;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',first_reader,'role','authenticated')::text,true);
 SELECT id INTO r FROM public."User" WHERE "authUserId"=first_reader;
 UPDATE public."MosqueMembership" SET status='SUSPENDED' WHERE "mosqueId"=first_m AND "userId"=r;
 PERFORM public.mp_reader_request(first_m);
 SELECT id INTO reader_id FROM public."MosqueReaderRequest" WHERE "mosqueId"=first_m AND "userId"=r;
 denied:=false;BEGIN PERFORM public.mp_workspace(first_m);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'pending_reader_allowed'; END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',first_auth,'role','authenticated')::text,true);
 PERFORM public.mp_reader_review(first_m,reader_id,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',first_reader,'role','authenticated')::text,true);
 q:=public.mp_workspace(first_m);IF (q->>'canWrite')::boolean IS NOT FALSE THEN RAISE EXCEPTION 'approved_reader_has_write'; END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',first_auth,'role','authenticated')::text,true);
 PERFORM public.mp_reader_revoke(first_m,reader_id);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',first_reader,'role','authenticated')::text,true);
 denied:=false;BEGIN PERFORM public.mp_workspace(first_m);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'revoked_reader_allowed'; END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',other_auth,'role','authenticated')::text,true);
 denied:=false;BEGIN PERFORM public.mp_workspace(first_m);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'cross_tenant_read_allowed'; END IF;checks:=checks+1;
 denied:=false;BEGIN PERFORM public.mp_save_record(first_m,'donasi','{}');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'cross_tenant_write_allowed'; END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',first_auth,'role','authenticated')::text,true);
 denied:=false;BEGIN PERFORM public.mp_save_record(first_m,'umkm','{}');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'package_elevation_allowed'; END IF;checks:=checks+1;
 denied:=false;BEGIN INSERT INTO public."MosqueAdmin"("mosqueId","userId") VALUES(first_m,first_u);EXCEPTION WHEN unique_violation THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'duplicate_admin_allowed'; END IF;checks:=checks+1;
 PERFORM public.mp_archive_record(first_m,rowid);q:=public.mp_workspace(first_m);
 IF jsonb_array_length(q->'records')<>0 THEN RAISE EXCEPTION 'archive_failed'; END IF;checks:=checks+1;
 denied:=false;BEGIN PERFORM public.mp_operator();EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'operator_escalation_allowed'; END IF;checks:=checks+1;
 denied:=false;BEGIN PERFORM public.mp_operator_tenants();EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'management_listing_escalation'; END IF;checks:=checks+1;
 denied:=false;BEGIN PERFORM public.mp_manage_tenant(first_m,'plan','ENTERPRISE','{}','Synthetic test');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'management_write_escalation'; END IF;checks:=checks+1;
 IF has_function_privilege('anon','public.mp_manage_tenant(uuid,text,text,jsonb,text)','EXECUTE') OR has_function_privilege('anon','public.mp_operator_tenants()','EXECUTE') THEN RAISE EXCEPTION 'anonymous_management_grant'; END IF;checks:=checks+1;
 PERFORM public.mp_apply_tenant('{"mosqueName":"Synthetic Application","city":"Jakarta","address":"Alamat pengujian sementara","contactName":"Synthetic Admin","whatsapp":"080000000000","plan":"BASIC"}');
 PERFORM public.mp_apply_tenant('{"mosqueName":"Synthetic Application","city":"Jakarta","address":"Alamat pengujian sementara","contactName":"Synthetic Admin","whatsapp":"080000000000","plan":"BASIC"}');
 denied:=false;BEGIN PERFORM public.mp_apply_tenant('{"mosqueName":"Synthetic Application","city":"Jakarta","address":"Alamat pengujian sementara","contactName":"Synthetic Admin","whatsapp":"080000000000","plan":"BASIC"}');EXCEPTION WHEN raise_exception THEN denied:=SQLERRM='application_rate_limit';END;
 IF NOT denied THEN RAISE EXCEPTION 'registration_limit_failed'; END IF;checks:=checks+1;
 UPDATE auth.users SET email_confirmed_at=NULL WHERE id=first_auth;
 denied:=false;BEGIN PERFORM public.mp_identity();EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'unverified_account_allowed'; END IF;checks:=checks+1;
 IF has_function_privilege('anon','public.mp_workspace(uuid)','EXECUTE') OR has_function_privilege('anon','public.mp_save_record(uuid,text,jsonb,uuid)','EXECUTE') OR has_table_privilege('authenticated','public."MosqueAdmin"','UPDATE') THEN RAISE EXCEPTION 'unsafe_grant'; END IF;checks:=checks+1;
 INSERT INTO launch_test_result VALUES(jsonb_build_object('tenants',45,'basic',15,'professional',15,'enterprise',15,'checks',checks,'elapsed_ms',round(extract(epoch FROM clock_timestamp()-started)*1000),'result','PASS: data isolation, one admin, reader denial, package gates, rate limit, verification, archive'));
END $$;
SELECT result FROM launch_test_result;
ROLLBACK;
